from pychain import contract, external, view, require, mapping, msg

@contract
class SimpleVoting:
    has_voted: mapping[address, bool] = {}
    vote_counts: mapping[uint, uint] = {}

    @external
    def vote(self, option: uint):
        require(not self.has_voted[msg.sender], "already voted")
        self.has_voted[msg.sender] = True
        self.vote_counts[option] += 1

    @view
    def votes_for(self, option: uint) -> uint:
        return self.vote_counts[option]

    @view
    def did_vote(self, voter: address) -> bool:
        return self.has_voted[voter]

from pychain import contract, external, payable, view, require, send_eth, msg, balance

@contract
class SimpleEscrow:
    buyer: address
    seller: address
    amount: uint = 0
    funded: bool = False
    released: bool = False

    def __init__(self, seller_address: address):
        require(seller_address != address(0), "seller cannot be zero address")
        self.buyer = msg.sender
        self.seller = seller_address

    @payable
    @external
    def fund(self):
        require(msg.sender == self.buyer, "only buyer can fund")
        require(not self.funded, "already funded")
        require(msg.value > 0, "fund with positive ETH")
        self.amount = msg.value
        self.funded = True

    @external
    def release(self):
        require(msg.sender == self.buyer, "only buyer can release")
        require(self.funded, "escrow is not funded")
        require(not self.released, "already released")
        self.released = True
        send_eth(self.seller, self.amount)

    @view
    def escrow_balance(self) -> uint:
        return balance()

from pychain import contract, event, external, view, require, emit, mapping, msg

@contract
class PointsRegistry:
    owner: address
    points: mapping[address, uint] = {}
    total_awarded: uint = 0

    @event
    def PointsAwarded(account: address, amount: uint):
        ...

    def __init__(self):
        self.owner = msg.sender

    @external
    def award(self, account: address, amount: uint):
        require(msg.sender == self.owner, "only owner can award points")
        require(account != address(0), "account cannot be zero address")
        require(amount > 0, "award must be positive")
        self.points[account] += amount
        self.total_awarded += amount
        emit(PointsAwarded, account, amount)

    @view
    def points_of(self, account: address) -> uint:
        return self.points[account]
